import { NextResponse } from "next/server";
import { getHubs } from "@/lib/hubs";
import { fetchFaresForHubs } from "@/lib/deals/fetchFares";
import { scoreAndFilter } from "@/lib/deals/scoreAndFilter";

function formatIsoDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

export async function GET() {
  const today = new Date();
  const departure = new Date(today);
  departure.setDate(departure.getDate() + 21);

  const returning = new Date(departure);
  returning.setDate(returning.getDate() + 10);

  const departureDate = formatIsoDate(departure);
  const returnDate = formatIsoDate(returning);

  const hubs = getHubs();
  const hubFares = await fetchFaresForHubs(hubs, departureDate, returnDate);
  const deals = await scoreAndFilter(hubFares);

  return NextResponse.json({
    hubs,
    fares: hubFares,
    deals,
  });
}
