import type { Hub } from "@/lib/hubs";

type FlightResult = {
  destination: string;
  airportCode: string;
  price: number;
  currency: string;
  departureDate: string;
  returnDate: string | null;
  airline: string;
  stops: number;
  source?: string;
};

type SearchApiResponse =
  | FlightResult[]
  | {
      results: FlightResult[];
    };

export type HubFare = {
  hub: Hub;
  price: number;
  airline: string;
  stops: number;
  departureDate: string;
  returnDate: string;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readString(obj: Record<string, unknown>, key: string): string | null {
  const value = obj[key];
  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

function extractHubDestinationCode(hub: Hub): string | null {
  if (!isRecord(hub)) return null;

  const directKeys = ["destination", "destinationCode", "airportCode", "code"] as const;
  for (const key of directKeys) {
    const code = readString(hub, key);
    if (code) return code.toUpperCase();
  }

  const destination = hub["destination"];
  if (isRecord(destination)) {
    const nestedCode = readString(destination, "code");
    if (nestedCode) return nestedCode.toUpperCase();
  }

  return null;
}

function normalizeSearchResponse(data: SearchApiResponse): FlightResult[] {
  if (Array.isArray(data)) return data;
  return Array.isArray(data.results) ? data.results : [];
}

export async function fetchFaresForHubs(
  hubs: Hub[],
  departureDate: string,
  returnDate: string
): Promise<HubFare[]> {
  try {
    const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3001";
    const response = await fetch(`${baseUrl}/api/search`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        origin: "MIA",
        departureDate,
        returnDate,
        tripType: "round-trip",
      }),
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch fares (${response.status})`);
    }

    const data = (await response.json()) as SearchApiResponse;
    const results = normalizeSearchResponse(data);
    const faresByAirport = new Map<string, FlightResult>();

    for (const result of results) {
      const code = result.airportCode.trim().toUpperCase();
      const current = faresByAirport.get(code);
      if (!current || result.price < current.price) {
        faresByAirport.set(code, result);
      }
    }

    const hubFares: HubFare[] = [];
    for (const hub of hubs) {
      const destinationCode = extractHubDestinationCode(hub);
      if (!destinationCode) continue;

      const match = faresByAirport.get(destinationCode);
      if (!match) continue;
      if (!match.returnDate) continue;

      hubFares.push({
        hub,
        price: match.price,
        airline: match.airline,
        stops: match.stops,
        departureDate: match.departureDate,
        returnDate: match.returnDate,
      });
    }

    return hubFares;
  } catch (error) {
    console.error("Failed to fetch fares for hubs:", error);
    return [];
  }
}
