import type { HubFare } from "@/lib/deals/fetchFares";
import { scoreFare, type FareHistory, type ScoreResult } from "@/lib/dealScore";
import { createClient } from "@supabase/supabase-js";

export type ScoredDeal = {
  hubFare: HubFare;
  scoreResult: ScoreResult;
};

export type DealsByContinent = Record<string, ScoredDeal>;

type FareHistoryRow = {
  airport_code: string;
  price: number;
  source: "seed" | "bootstrap" | "live";
  recorded_at: string;
};

export async function scoreAndFilter(
  hubFares: HubFare[]
): Promise<DealsByContinent> {
  if (hubFares.length === 0) return {};

  const supabaseUrl = process.env.SUPABASE_URL;
  const supabaseAnonKey = process.env.SUPABASE_ANON_KEY;
  if (!supabaseUrl || !supabaseAnonKey) {
    console.error("Supabase env vars are missing: SUPABASE_URL and SUPABASE_ANON_KEY");
    return {};
  }

  const supabase = createClient(supabaseUrl, supabaseAnonKey);
  const airportCodes = [...new Set(hubFares.map((fare) => fare.hub.destination.toUpperCase()))];

  const { data, error } = await supabase
    .from("fare_history")
    .select("airport_code, price, source, recorded_at")
    .in("airport_code", airportCodes);

  if (error) {
    console.error("Failed to fetch fare history:", error);
    return {};
  }

  const rows: FareHistoryRow[] = Array.isArray(data) ? (data as FareHistoryRow[]) : [];
  const history: FareHistory[] = rows.map((row) => ({
    airportCode: row.airport_code,
    price: row.price,
    source: row.source,
    recordedAt: row.recorded_at,
  }));

  const dealsByContinent: DealsByContinent = {};

  for (const hubFare of hubFares) {
    const scoreResult = scoreFare(hubFare.price, hubFare.hub.destination, history);
    if (!scoreResult.isGenuineDeal) continue;

    const continent = hubFare.hub.continent;
    const existing = dealsByContinent[continent];

    if (!existing || scoreResult.score > existing.scoreResult.score) {
      dealsByContinent[continent] = {
        hubFare,
        scoreResult,
      };
    }
  }

  return dealsByContinent;
}
